import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// Schema for the Circular Ring Trace


export type RingTraceProps = Record<string, any>;

const RingTrace: React.FC<RingTraceProps> = ({
  traceColor = "#facc15", // Flat yellow stroke
  baseColor = "transparent", // Hidden base for "stroke only" look
  transparentBackground = true,
  backgroundColor = "#000000",
  durationInSeconds = 3,
  strokeWidth = 15,
  radiusPercentage = 35,
  glowIntensity = 0, // Default to 0 for no glow
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Timing
  const durationInFrames = durationInSeconds * fps;
  
  // Animation progress (0 to 1) with ease-out for a smooth finish
  const progress = interpolate(
    frame,
    [0, durationInFrames],
    [0, 1],
    { extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) }
  );

  // Layout Dimensions
  const minDim = Math.min(width, height);
  const radius = (minDim / 2) * (radiusPercentage / 100);
  const circumference = 2 * Math.PI * radius;
  const cx = width / 2;
  const cy = height / 2;

  // Stroke Animation Logic
  // Animate dashoffset from circumference (hidden) to 0 (fully drawn)
  const strokeDashoffset = interpolate(
    progress,
    [0, 1],
    [circumference, 0]
  );

  // Background
  const finalBg = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: finalBg }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        {/* Rotate -90deg to start drawing from the top (12 o'clock) */}
        <g transform={`rotate(-90, ${cx}, ${cy})`}>
          
          {/* Static Underlying Ring (The "Track") */}
          <circle
            cx={cx}
            cy={cy}
            r={radius}
            fill="none"
            stroke={baseColor}
            strokeWidth={strokeWidth}
          />

          {/* Animated Highlight Trace - Solid sharp edge, no blur/glow */}
          <circle
            cx={cx}
            cy={cy}
            r={radius}
            fill="none"
            stroke={traceColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            shapeRendering="geometricPrecision"
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default RingTrace;